INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Puzzle Chronicles', 'Enter the dark and savage lands of the Ashurin Empire as you battle to avenge the atrocities the Empire brought upon your tribesmen. On your heroic quest to topple the Empire you will fight fierce beasts and battle hardened warriors in this new Puzzle RPG hybrid game. Featuring an active puzzle combat mechanic, deep story, and robust character development Puzzle Chronicles will bring you into the next era of Puzzle RPGs.' FROM games WHERE igdb_id = 10732 ON CONFLICT (game_id, language_code) DO NOTHING;
