INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flip''s Twisted World', 'Flip’s Twisted World is a 3D puzzle-platformer that follows the adventures of Flip who is accidentally trapped inside a world where up and down are just a matter of perspective. By turning a magic cube, he is able to turn the entire world, opening up new paths and possibilities. Players must think “outside of the box” as they navigate the world that is literally in the palms of their hands.' FROM games WHERE igdb_id = 4857 ON CONFLICT (game_id, language_code) DO NOTHING;
