INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Penalty Shoot-Out Soccer: 2010 World Champion', 'Are you crazy about World Cup ? Are you a soccer enthusiast ? Now you will be able to experience a different soccer!! Penalty Shoot-Out Soccer: 2010 World Champion will bring you different experience of Soccer! Choose a country you like to play against other 31 countries and you can defeat them by penalty kick. Win the World Champion for yourself or for the country you like! No more hesitation! Simple control will greatly improve your penalty kick skills! Endless fun!!!' FROM games WHERE igdb_id = 174233 ON CONFLICT (game_id, language_code) DO NOTHING;
