INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Islash', 'iSlash is an addictive slashing puzzle where your finger is your weapon. Swipe to slash your way through 240 amazing levels(more to come for free). Keep an eye on the ninja stars; some are fast, some are ghosts, but all are deadly. Destroy most of the play-shape, and you''ll advance to the next one. Open your ninja senses and let the fun begin!' FROM games WHERE igdb_id = 343617 ON CONFLICT (game_id, language_code) DO NOTHING;
