INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sid Meier''s Civilization V', 'Sid Meier''s Civilization V is a turn-based strategy game where the player leads a civilization from the stone-age all the way to future tech, there is more than one way to win, achieving one of a number of different victory conditions through research, exploration, diplomacy, expansion, economic development, government and military conquest. You will face other civilizations, either online as other people or played by the computer, civilization 5 features a advanced diplomacy system when dealing with computer controlled civs or computer controlled city-states.' FROM games WHERE igdb_id = 866 ON CONFLICT (game_id, language_code) DO NOTHING;
