INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Day of the Tiki', 'Day of the Tiki was announced as a 2D arcade platformer based on the cult web series Tiki Bar TV, developed by Secret Lab and published by the show''s creators. While some game databases list it as released in 2009, there''s no verifiable evidence that it was ever publicly distributed. No playable builds, demos, or archived files have surfaced, and the developer no longer references the project. It''s likely the game was postponed to 2010 and quietly cancelled, or released in such a limited capacity that no digital trace remains.' FROM games WHERE igdb_id = 90950 ON CONFLICT (game_id, language_code) DO NOTHING;
