INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hyperdimension Neptunia', 'This unique RPG features game consoles personified as goddesses, CPUs (Console Patron Units), who you can customize visually with equipment to enhance their stats. Players take the role of Neptune and follow her quest to save the captive Histoire. This leads her to face the corrupt monsters ravaging the world of Gamindustri unleashed by the evil Arfoire.' FROM games WHERE igdb_id = 7319 ON CONFLICT (game_id, language_code) DO NOTHING;
