INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tamagotchi no Pichi Pichi Omisecchi', 'Tamagotchi no Pichi Pichi Omisecchi is a Japan-exclusive Nintendo DS entry in the Tamagotchi Corner Shop spin-off series. Set on Pichi Pichi Island, players choose a Tamagotchi partner and help run and upgrade a variety of island shops through mini-games. The game features 3D-style graphics, an explorable game world, and introduces ingredient-gathering mechanics—like fishing, farming, and market shopping—to restock and manage the shops. The storyline centers on helping the island hold together as players unravel an environmental mystery affecting fish and crops.' FROM games WHERE igdb_id = 77622 ON CONFLICT (game_id, language_code) DO NOTHING;
