INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spider-Man: Shattered Dimensions', 'Spider-Man: Shattered Dimensions blends together the many alternate universes of the world-famous webslinger with four unique takes on Spider-Man''s history in comics. In the game, Spider-Man attempts to retrieve a piece of a tablet that''s been scattered across multiple parallel dimensions, and in doing so he crosses over to storylines famous to comic book aficionados as variant tellings (including The Amazing Spider-Man, Spider-Man 2099, Spider-Man Noir & Ultimate Spider-Man) of the Spider-Man mythology.' FROM games WHERE igdb_id = 553 ON CONFLICT (game_id, language_code) DO NOTHING;
