INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mimana Iyar Chronicle: First Edition', 'Mimana Iyar Chronicle blends the traditional RPG elements of vast map exploration and treacherous dungeon spelunking. Engage in fast-paced battles in a quasi-3D environment where you control the character''s movement and actions, and strategically command your party to turn the tide of battle. Your actions dictate how the story unfolds, through numerous fully-voiced event sequences.' FROM games WHERE igdb_id = 42711 ON CONFLICT (game_id, language_code) DO NOTHING;
