INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Diamond Dan', 'Dragged into Archeology by his uncle, Dan decides to take matters into his own hands. He discovers ancient temples with long lost treasures and menacing traps. Dan follows the clues found in the temples which leads him on a trip across the world, bringing him ever closer to making a sensational discovery. You will help Dan navigate past the traps, collect treasure and reach the bottom of the temples where Dan can find the treasure map that leads him further on his journey.' FROM games WHERE igdb_id = 9821 ON CONFLICT (game_id, language_code) DO NOTHING;
