INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RayStorm HD', 'The classic shooting game returns with the original gameplay and newly updated graphics in RAYSTORM HD. You control the R-GRAY, a fighter plane equipped with a lock-on laser system, and battle your way through eight stages. A variety of game modes includes Arcade Mode and Extra Mode, with four selectable planes including the untested new R-GEAR. Rankings can be registered, and replay data can be uploaded and downloaded online.' FROM games WHERE igdb_id = 47448 ON CONFLICT (game_id, language_code) DO NOTHING;
