INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Raze', 'Raze is a third-person platformer shooter, developed on March 3, 2008 and released March 5, 2010, Raze involves on the battle between the Aliens and the Humans in a struggle for survival . As the Humans, you play as the Raze Soldier. On the other hand, you play as a Desert Alien. These games feature futuristic and versatile weapons such as the Assault Rifle and Sniper Rifle. Would you play as the Humans and fight for ultimate survival? Or would you instead be with the aliens and fight for the extinction of Humans?' FROM games WHERE igdb_id = 165331 ON CONFLICT (game_id, language_code) DO NOTHING;
