INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SingStar: Apres-Ski Party 2', 'Like its predecessor, SingStar: Apres Ski Party 2 is a collection of party songs. While most of them are in German language and/or were only successful in German speaking territory, there are also a few international hits included. There are no gameplay changes: player(s) sing into a microphone and the game gives points based on the performance. The only basis of assessment is if the correct note is hit with the correct timeing; the sung words or octave does not play into the result.' FROM games WHERE igdb_id = 44704 ON CONFLICT (game_id, language_code) DO NOTHING;
