INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metal Gear Solid: Peace Walker - Collector''s Edition', 'Metal Gear Solid: Peace Walker is an action-adventure stealth video game developed by Kojima Productions and published by Konami for the PlayStation Portable in 2010. It is the seventh Metal Gear game written, directed, and designed by Hideo Kojima, as well as the second action-based Metal Gear title made specifically for the PSP, following Metal Gear Solid: Portable Ops.' FROM games WHERE igdb_id = 42712 ON CONFLICT (game_id, language_code) DO NOTHING;
