INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Unexpected Journey', 'Unexpected Journey follows reporter Lina Woodberry on an assignment aboard a cruise ship to interview celebrities. After a sudden turn of events, she finds herself in remote, perilous locations and must make her way back to civilization. Gameplay centers on finding listed objects in richly detailed scenes, opening containers to reveal items, and solving spot‑the‑difference and other mini‑games. Select items are stored in an inventory film strip for drag‑and‑drop interactions, while a hint meter recharges over time or via collectible batteries' FROM games WHERE igdb_id = 361585 ON CONFLICT (game_id, language_code) DO NOTHING;
