INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cars Toon Mater''s Tall Tales', 'Featuring fast-paced, multiplayer, family fun, Cars Toon: Mater''s Tall Tales offers a large collection of pick-up-and-play games inspired by the Mater''s Tall Tales animated short series. The game will bring Mater together with Lightning McQueen and the Cars gang for a new set of adventures, capturing the endearing sense of humor of everyone''s favorite tow truck. Players will join Mater and his pals as they relive the wild stories he conjures up about hilariously unpredictable events that may or may not have taken place.' FROM games WHERE igdb_id = 50687 ON CONFLICT (game_id, language_code) DO NOTHING;
