INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fast Striker', 'Fast Striker is a Shoot-''Em-Up game, developed and published by NG:DEV.TEAM, which was released in Japan in 2012D arcade shooting game with emphasis on scoring originally developed for NEO·GEO. The game lets the player choose between 3 game modes with different scoring systems. Novice Mode for beginners, Original Mode for classic Shoot’ em Up players and Maniac for very experienced players. It features six stages of excellent 2D arcade game play with over 40 unique enemy types, super smooth 3D scrolling backgrounds, huge CGI bosses and it features the biggest megabit count ever since the beginning of NEO·GEO games0.' FROM games WHERE igdb_id = 9125 ON CONFLICT (game_id, language_code) DO NOTHING;
