INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Farm Frenzy 3: American Pie', 'Can you keep up with Scarlett and the latest advancements in technology as you grow crops, feed animals, collect produce and manufacture goods? Of course you can! Just don''t let the zany new animations distract you from the task at hand. Featuring 90 all-new levels, packed with never-before-seen characters, buildings and challenges, Farm Frenzy 3: American Pie promises a bumper crop of fun.' FROM games WHERE igdb_id = 16094 ON CONFLICT (game_id, language_code) DO NOTHING;
