INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trauma Team', 'Encounter unprecedented depth across six distinct fields of medicine: play as a general surgeon, diagnostician, E.M.T., orthopedic surgeon, endoscope technician, and medical examiner. Follow the story as never before with all-new dynamic story sequences inspired by Japanese animation and comics; each dramatic chapter comes vividly to life with distinct style! Hand-drawn art, innovative animation, and quality voice acting perfectly capture the raw intensity, excitement, and danger of every heart-pounding moment!' FROM games WHERE igdb_id = 1527 ON CONFLICT (game_id, language_code) DO NOTHING;
