INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Go to Hell', 'Just go to hell and find out it''s secret in this ultimate puzzle/arcade/platform game. You have to dig all the way down through caves filled with water, lava, boulders and enemies. You can avoid suffocating and kill enemies controlling flow of water and lava by digging holes in walls of caves. You can also push a boulder on the filthy worms and bats.' FROM games WHERE igdb_id = 218538 ON CONFLICT (game_id, language_code) DO NOTHING;
