INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Kid: Fortress of Peril', 'Battle Kid: Fortress Of Peril is a homebrew 2D platform video game, released in February 2010 for the Nintendo Entertainment System, created by Sivak Games, and published through Retrozone with the cover art designed by Larry Bundy Jr. Unlike most games in the modern era, Battle Kid is available for purchase only on a physical NES cartridge. While there has been a demand for a downloadable version, the developer has stated that the game is currently not planned to be released on any other formats due to a contract with Retrozone.' FROM games WHERE igdb_id = 11145 ON CONFLICT (game_id, language_code) DO NOTHING;
