INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Game of Hockey', 'A Game of Hockey is an update to an old classic. In this game, the player controls the left two paddles and tries to guard his or her goal from the puck while trying to bounce the puck into the computer''s goal.' FROM games WHERE igdb_id = 92320 ON CONFLICT (game_id, language_code) DO NOTHING;
