INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Bears: GO', 'Battle Bears: GO is a top-down shooter (bird''s-eye view), meaning players view the game a bird''s eye view. It also has a two-player co-op mode. Players shoot with 3 different weapons and have lots of different power-ups to help fight off the Huggables. It is only available on the iPad, thought to be caused by the fact the game was too small for an iPhone/iPod Touch screen.' FROM games WHERE igdb_id = 62320 ON CONFLICT (game_id, language_code) DO NOTHING;
