INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chronicles of Mystery: The Legend of the Sacred Treasure', 'Chronicles of Mystery: The Legend of the Sacred Treasure is a compelling adventure told through hidden-object clues and riddles. Experience an intriguing plot full of twists and turns that create an atmosphere of danger, with beautiful graphics of exotic locations, including Paris and Ethiopia. The game also has hidden-object puzzles and a variety of mini-games to challenge players'' skills.' FROM games WHERE igdb_id = 105441 ON CONFLICT (game_id, language_code) DO NOTHING;
