INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Farm Frenzy: Pizza Party', 'Pizza lovers unite! It''s time to return to the farm to create your favorite food! You''ll start out by growing grass, feeding animals and collecting produce. Then you''ll turn your goods into the ingredients you need to make different pizzas! From China to Germany, and from Italy to New York City -- where pizza is considered one of the main food groups -- your mouth-watering creations will be enjoyed around the world.
