INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Frozen Essence', 'This is an otome visual novel, an interactive story with choices that affect the ending. You start off inside your realm with a few bodyguards to protect you. You may find love, or it’ll end differently. Each path’s story differs greatly depending on the path you land on.' FROM games WHERE igdb_id = 125570 ON CONFLICT (game_id, language_code) DO NOTHING;
