INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harry Potter and the Deathly Hallows: Part 1', 'Harry Potter and the Deathly Hallows: Part 1 is an adaption of the movie of the same name. The player takes the role of Harry Potter on his quest to find the Horcruxes, the source of the villain''s immortality. The gameplay is similar to Harry Potter and the Goblet of Fire, as it is an action video game, not a video game of making potions, playing Quidditch or exploring Hogwarts. There is no RPG iteration of the game, unlike with previous titles.' FROM games WHERE igdb_id = 4904 ON CONFLICT (game_id, language_code) DO NOTHING;
