INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Winx Club Rockstars', 'In Winx Club Rockstars the fairy friends head out on a new kind of adventure, swapping their magic for guitars and microphones and whipping up a fairy rock star frenzy on stage. Fans will be able to play their favorite Winx Club fairy, choose one of four musical instruments to rock out with, and practice more than 12 exclusive Winx Club songs as they aim for the big time. Mastering the rhythmic gameplay and hitting high scores gives players the chance to style and customize their characters to make an even bigger splash when they''re under the lights.' FROM games WHERE igdb_id = 25193 ON CONFLICT (game_id, language_code) DO NOTHING;
