INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fallout: New Vegas', 'In this first-person Western RPG, the player takes on the role of Courier 6, barely surviving after being robbed of their cargo, shot and put into a shallow grave by a New Vegas mob boss. The Courier sets out to track down their robbers and retrieve their cargo, and winds up getting tangled in the complex ideological and socioeconomic web of the many factions and settlements of post-nuclear Nevada.' FROM games WHERE igdb_id = 16 ON CONFLICT (game_id, language_code) DO NOTHING;
