INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ikusa Megami Verita', 'The wandering God-Slayer Serika, who''s still searching for his purpose. The half-demon king of Menfill, Loui, who just won the war, but lost his wife in it. This is the story of two infamous heroes and how their paths in life inevitably cross each other, and the conflict that it brings. While on the backdrop of the setting, various ancient forces rear their head and the temple of Marsterrie starts moving.' FROM games WHERE igdb_id = 208286 ON CONFLICT (game_id, language_code) DO NOTHING;
