INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Golden Sun: Dark Dawn', 'After going dark six years ago, 2010 will see a new dawn. Golden Sun DS updates the popular portable Golden Sun role-playing series with an impressive graphical style. This installment follows the story of the previous heroes'' descendants and immerses players into the magic of its adventure by pushing the boundaries of intuitive touch-screen controls.' FROM games WHERE igdb_id = 1174 ON CONFLICT (game_id, language_code) DO NOTHING;
