INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flugrettung: Die Simulation', 'Flugrettung: Die Simulation is a helicopter flight rescue simulation where players assume the role of an air rescue pilot leading a team of emergency doctors, paramedics, and dog handlers. Players navigate over 100 rescue missions including avalanches, car accidents, and industrial fires, making strategic decisions in time-critical situations. The game features realistic flight physics, 3D landscapes with map-based navigation, and detailed graphics designed to create an immersive rescue operation experience.' FROM games WHERE igdb_id = 334884 ON CONFLICT (game_id, language_code) DO NOTHING;
