INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pixel Fireplace', 'Pixel Fireplace is a cozy, type-controlled simulation. Strike a MATCH, throw LOGS onto the crackling fire, and watch them slowly burn down to ash in real-time. Discover more interactive commands like MARSHMALLOW, SMORE, HOTDOG, FIRECRACKER, NEWSPAPER, RED, SUNSET, WATER, or just sit back, turn the lights down and enjoy.' FROM games WHERE igdb_id = 134645 ON CONFLICT (game_id, language_code) DO NOTHING;
