INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('clash-of-the-titans-the-videogame', 6938, '2010-05-28', 38, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4zla.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/uculzhtfzfxdljfy4zjz.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Clash of the Titans: The Videogame', 'Set in the timeless grandeur of Greek mythology, Clash of the Titans immerses players into the epic battle for dominance between the human race and the powerful gods Hades and Zeus. Through vast landscapes of swamps, mountains and the underworld, two modes of play let players embody Perseus'' adventure from the film, or take on original new bosses in fresh, dynamic adaptations of one of the greatest mythological stories ever told. This action-adventure game play arms players with an ever-changing arsenal of weapons and powers. Players can journey solo or team up with friends to complete quests as they encounter a roster of legendary villains including Medusa and the sea monster known as The Kraken.' FROM games WHERE igdb_id = 6938 ON CONFLICT (game_id, language_code) DO NOTHING;
