INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jinx 3: Escape From Area Fitty-Two', 'Jinx 3: Escape From Area Fitty-Two is a point-and-click adventure game where you control multiple characters—Jinx, the Professor, and the ELF—to solve puzzles and escape a secret government facility. Success requires switching between characters, using their unique abilities, and interacting with objects in the correct sequence to progress through interconnected puzzles.' FROM games WHERE igdb_id = 383493 ON CONFLICT (game_id, language_code) DO NOTHING;
