INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Game Formerly Known as Hidden Nazi Mode', 'The Game Formerly Known as Hidden Nazi Mode was, in fact, formerly known as Hidden Nazi Mode. As such it was a failed experiment, detailed in the accompanying essay. In this release the Nazi mode has been removed, and what remains is, as the subtitle says, "a cute game for unattended young children". It involves bunnies and lots of hints.' FROM games WHERE igdb_id = 214898 ON CONFLICT (game_id, language_code) DO NOTHING;
