INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Family Feud: Decades', 'Family Feud: Decades, also known as Family Feud: 2011 Edition, is a trivia game based on the TV game show Family Feud. The game is set across four different decades: the 70s, 80s, 90s and 2000s decades. Each decade is represented by a different stage set, which is based on the TV set of that era.
