INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ys: The Oath in Felghana - Premium Edition', 'Ys: The Oath in Felghana once again follows the adventures of friends Adol and Dogi who find themselves making an unannounced visit to Dogi''s hometown of Redmont in the land of Felghana. Since his departure eight years earlier, Dogi finds himself returning home to find that things have changed dramatically, and not for the better.
