INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pucchin Puzzle', 'Pucchin Puzzle provides a variation on the nonogram puzzle genre. Players control a square-shaped dog on a grid; players need to mark specific squares in the grid to reveal pixel-art pictures, following hints on the top and left sides of the screen. The game''s puzzles are divided into many different themed worlds, laid out on a world map, with different graphical styles and different costumes for the main characters in each different world.' FROM games WHERE igdb_id = 288173 ON CONFLICT (game_id, language_code) DO NOTHING;
