INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Prince of Persia: The Forgotten Sands', 'Prince of Persia: The Forgotten Sands is a multi-platform video game produced by Ubisoft which was released on May 18, 2010, in North America and on May 20 in Europe. The games mark a return to the storyline started by Prince of Persia: The Sands of Time. Prince of Persia: The Forgotten Sands is the title of four separate games with different storylines. The main game was developed for PlayStation 3, Xbox 360, and Microsoft Windows, while the other three are exclusives for the PlayStation Portable, Nintendo DS, and Wii.' FROM games WHERE igdb_id = 2468 ON CONFLICT (game_id, language_code) DO NOTHING;
