INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Club Penguin: Game Day!', 'It''s Game Day! Are you ready for the challenge? Play in the first ever Club Penguin island-wide Game Day challenge only on Wii console. Create your own penguin, join a team and compete against other penguin teams in Java Jump, Sled & Slide, Sumo Smash, Fast Freeze and more. Compete to see who is the best team once and for all!' FROM games WHERE igdb_id = 92058 ON CONFLICT (game_id, language_code) DO NOTHING;
