INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Achievement Unlocked 2', 'Achievement Unlocked 2 is a platformer meta-game based on getting achievements, where you control a little blue elephant exploring the facility where it is mysteriously placed, trying to find an exit. It is the sequel to Achievement Unlocked and features the same elephant protagonist as in the first game, as well as in many other jmtb02 games.' FROM games WHERE igdb_id = 165420 ON CONFLICT (game_id, language_code) DO NOTHING;
