INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Minimonos Flight', 'Flying monkeys, wind clouds, and trampolines: what more could you want in a game? Play MiniMonos Flight to become an enterprising monkey with leaves for wings. Fly around, collecting wind clouds and avoiding pollution clouds. Stay aloft as long as you can and fly as far and as high as you possibly can! You can even shoot up into space to see gorgeous stars -- but be careful! Flapping those wings burns up lots of energy, and if you find yourself plummeting to the ground, you’ll need to land on a trampoline if you want to keep going.' FROM games WHERE igdb_id = 383765 ON CONFLICT (game_id, language_code) DO NOTHING;
