INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Twin Blades: The Reaping Vanguard', 'TwinBlades is a frantic shooter game set in a medieval era with unique manga-like graphics. Help the nun defeat evil with some heavy zombie-killing action across multiple environments, venture through the city market, the cemetery, a chapel in ruins and the city''s outskirts to purge the town of all its living-dead inhabitants!' FROM games WHERE igdb_id = 19890 ON CONFLICT (game_id, language_code) DO NOTHING;
