INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Traders', 'This epic space pirate RPG offers a deep and challenging world and economy to Star Trading captains. You must navigate the waters of Quadrant politics and choose sides among the constantly conflicting Factions, or take the risk to stay independent. Enjoy endless replay value in this deep space civ and trading simulation which allows you to take any path you want as a captain. Act as a pirate against the merchants using the great shipping lanes, join the Solar War as a military captain, or hunt targets across the Quadrant as a fearsome bounty hunter!' FROM games WHERE igdb_id = 69581 ON CONFLICT (game_id, language_code) DO NOTHING;
