INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Room', 'The Room Tribute (also known as The Room: The Game) is a point-and-click adventure game released on September 3, 2010, that serves as an unofficial adaptation of the 2003 film The Room directed by Tommy Wiseau. It was programmed by Newgrounds founder Tom Fulp, with artwork by Newgrounds staff member Jeff "JohnnyUtah" Bandelin, and music by animator Chris O''Neill. The game was designed in the style of 16-bit graphics, much like similar games based on the films Tremors and The Hunger Games for Newgrounds'' own 2010 and 2012 April Fools jokes.' FROM games WHERE igdb_id = 8468 ON CONFLICT (game_id, language_code) DO NOTHING;
