INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Swarm Arena', 'Get ready for a brand new experience! Take control of a virtual organism, develop your moves and become one with the swarm – then the game has only just begun. Swarm Arena’s fresh and deep gameplay is a journey from relaxing aesthetics over mind-blowing action to pure tactics. Be fast. Be precise. Or simply enjoy the experience.' FROM games WHERE igdb_id = 15025 ON CONFLICT (game_id, language_code) DO NOTHING;
