INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dimensity', 'DIMENSITY is an immersive, intensely paced role-playing / action game in a unique 3D fantasy setting. Adventure through hostile lands and fight numerous enemies in a world torn by war. Be part of plots defending the crown, fighting for the freedom of your people or taking side paths discovering treasures and facing ancient fearsome foes.' FROM games WHERE igdb_id = 16152 ON CONFLICT (game_id, language_code) DO NOTHING;
