INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Real Soccer 2010', 'Real Soccer 2010 is the seventh entry in Gameloft''s annual series of mobile football games. Like with previous releases the game is played from an isometric bird''s eye view. The gameplay works the same as before and has the same controls with the same moves being possible to do. This includes performing lobs, flip-flap tricks and one-two passing.' FROM games WHERE igdb_id = 67151 ON CONFLICT (game_id, language_code) DO NOTHING;
