INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Born Into Darkness', 'Amber Blythe is the night curator at the Bostonian Museum, where she is happily surrounded by artifacts and relics of the past. Considering she''s spent the last two hundreds years as a vampire, she feels right at home. When the new assistant curator, Nathaniel Black, invites her to help him find the legendary Shroud of Lazarus, the two embark on a worldwide hidden object adventure that may ultimately result in Amber regaining her humanity.' FROM games WHERE igdb_id = 341059 ON CONFLICT (game_id, language_code) DO NOTHING;
