INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Epic Mickey', 'Disney Epic Mickey is an action-adventure platforming game for Wii console that sends Mickey Mouse on an epic journey of creativity and discovery. As Mickey, the player is propelled into Wasteland, an alternate world made up of Disney''s forgotten creative efforts, and is given the power to wield paint and paint thinner to dynamically change the world while determining Mickey''s path to becoming an epic hero.' FROM games WHERE igdb_id = 1509 ON CONFLICT (game_id, language_code) DO NOTHING;
