INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Atelier Rorona: The Alchemist of Arland - Limited Edition', 'Atelier Rorona is the eleventh installment in the Atelier series, and it continues the series'' emphasis on item synthesis. The game is the first title in the series to be developed for PlayStation 3, and it is also the first to utilize 3D models as opposed to the 2D sprites in earlier titles. A sequel titled Atelier Totori: The Adventurer of Arland, which takes place five years after the end of Atelier Rorona, was released in Japan on June 24, 2010.' FROM games WHERE igdb_id = 44600 ON CONFLICT (game_id, language_code) DO NOTHING;
