INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shark Attack', 'It is the year 30XX and Earth is at peace thanks to the Shark Attack Force, a group of humanoid sharks made to fight terrorists and criminals. The human race had launched a new space shuttle to explore the galaxy, and despite its success of discovering new life forms and planets, a mysterious life form breached the shuttle and directed the ship toward Earth. With Earth now at risk of war and invasion, Shark Attack has been sent to deal with this threat.' FROM games WHERE igdb_id = 134536 ON CONFLICT (game_id, language_code) DO NOTHING;
