INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '101-in-1 Megamix', '101-in-1 Megamix is a collection of 101 games offering a healthy serving of adventure, action and puzzle gameplay galore that is fun for all family. Featuring 101 games that take you from the depth of the ocean to the Wild West... From the Stone Age to space racing... 101-in-1 Megamix boasts a unique visual style, a wide variety of unlockable games and prizes, and superb multiplayer action. Come channel surfin'' through 8 different TV stations and play through a series of zany TV shows tailored to all sorts of themes, each packed to the brim with insane adventures and delightful challenges!' FROM games WHERE igdb_id = 42764 ON CONFLICT (game_id, language_code) DO NOTHING;
