INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Family Pirate Party', 'Daddy, Mommy, Sarah, and Billy make their return as pirates sailing the seas and skies! Roll the dice and sail through the islands to gather the treasures each island holds. The person with the most gold at the end wins! Family Pirate Party shines with its appealing cel-shaded graphics and endearing music. Challenge up to three other players, be they friends, the CPU, or both, for some four-player board-game fun. Do you have it in you to defeat your opponents and become the king of Family Pirate Party!?' FROM games WHERE igdb_id = 50700 ON CONFLICT (game_id, language_code) DO NOTHING;
