INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Get fit with Mel B', '"Get fit with Mel B" is a sporty workout game that will bring you right into the action. Together with a healthy nutrition plan shaped for your needs, Scary Spice will guide you through various modes like dance fit, cardio, step, pump and tone and kickboxing. The game also supports a large variety of fitness accessories that will make the workout even more effective.' FROM games WHERE igdb_id = 11624 ON CONFLICT (game_id, language_code) DO NOTHING;
