INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Red Dead Redemption', 'A modern-day Western epic, Red Dead Redemption takes John Marston, a relic from the fast-closing time of the gunslinger, through an open world filled with wildlife, mini-games, and shootouts. Marston sets out to hunt down his old gang mates for the government, who have taken away his family. Along his journey, he meets many characters emblematic of the Wild West, heroism, and the new civilization.' FROM games WHERE igdb_id = 434 ON CONFLICT (game_id, language_code) DO NOTHING;
