INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Madden NFL 11', 'Madden NFL 11 re-energizes the game of football with a fun and exhilarating experience to ignite the passion of every NFL fan. Whether you’re rekindling an old rivalry, putting your spin on the best moments of 2009, or building the ultimate dynasty in Franchise mode, Madden NFL 11 makes every day feel like Sunday. Experience the passion for football shared by Gus Johnson and Cris Collinsworth as they call the action on the field. Fight for fumbles, design your own plays, and feel what it''s like to be an NFL superstar with Madden NFL 11, the ultimate NFL experience on PlayStation Portable.' FROM games WHERE igdb_id = 4986 ON CONFLICT (game_id, language_code) DO NOTHING;
