INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sports Champions', 'Sports Champions is a 2010 sports video game developed by San Diego Studio and Zindagi Games and published by Sony Computer Entertainment for PlayStation 3, which utilizes PlayStation Move. It was officially unveiled at the 2010 Game Developers Conference in San Francisco. The game is a collection of modern and medieval sports games published by Sony Computer Entertainment and is jointly developed by San Diego Studio and Zindagi Games as a launch game for the PlayStation Move which would be bundled with the controller in several regions.' FROM games WHERE igdb_id = 18237 ON CONFLICT (game_id, language_code) DO NOTHING;
