INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('spectral-force-genesis', 21090, '2010-04-16', 55, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8kzi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ltpuk9iirchpn8vqcus3.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spectral Force Genesis', 'Spectral Force makes its first appearance on the Nintendo DS featuring over 150 characters, a high level of strategic gameplay and a truly epic story. It''s quite simply the perfect introduction to the Spectral Force series and the fantasy world of Neverland. Spectral Force is based in the fantasy world of Neverland where humans and demons struggle for supremacy against each other over 40 countries. Each new game in the series adds another page to the history giving it a depth and complexity almost unrivalled within the RPG genre. In Spectral Force Genesis, the player will be able to take command of a country and using a mix of strategy, diplomacy and force, attempt to bring the whole kingdom under unified rule. You will meet a lot of different characters along the way and as events gradually unfold the player will make decisions which will trigger a whole host of surprising events and scenarios.' FROM games WHERE igdb_id = 21090 ON CONFLICT (game_id, language_code) DO NOTHING;
