INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('scooby-doo-mystery-incorporated-crystal-cove-online', 371784, '2010-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coammf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4du1.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scooby-Doo! Mystery Incorporated: Crystal Cove Online', 'Scooby-Doo! Mystery Incorporated Crystal Cove Online was a game available on Cartoon Network''s official website to coincide with the airing of Scooby-Doo! Mystery Incorporated season 1. The levels of the game largely corresponded with the episodes of the first season, even featuring the exact same monsters and culprits. Levels would unlock weekly after new Mystery Incorporated episodes aired to prevent the plots from being spoiled.' FROM games WHERE igdb_id = 371784 ON CONFLICT (game_id, language_code) DO NOTHING;
