INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hello, Good-bye', 'Hello, Good-bye is a Japanese adult visual novel. The primary focus of the game is the appeal of the four female main characters. The story resolves around the protagonist, Kaito Toubu, a secret agent tasked with infiltrating the demilitarised territory of Morino in an alternate universe Japan.' FROM games WHERE igdb_id = 111803 ON CONFLICT (game_id, language_code) DO NOTHING;
