INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nightfall Mysteries: Asylum Conspiracy', 'Help Christine explore the spooky Ashburg Asylum and find her missing grandfather in this dark Hidden Object game! Travel to the eerie grounds of Ashburg and work your way through spine-chilling locations. Solve unique puzzles to progress deeper into the asylum, and closer to Christine’s grandfather. Meet interesting characters, unravel a mystery, and uncover an evil plot in Nightfall Mysteries: Asylum Conspiracy!' FROM games WHERE igdb_id = 125304 ON CONFLICT (game_id, language_code) DO NOTHING;
