INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'This is the Only Level Too', 'Do you like jumping? Do like spikes? There are both in this game, and a handful of different ways to try to beat the only level in the game. Confront each new stage challenge with a sort of heart and dignity that we can only befall on our most noble of creatures. Also you can unlock a velociraptor, how cool how is that?' FROM games WHERE igdb_id = 198112 ON CONFLICT (game_id, language_code) DO NOTHING;
