INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Take a Break''s Puzzle Bonanza', 'Following on from the success of Take a Break’s Puzzle Master comes an all-new puzzle title for the Nintendo DS – Take a Break’s Puzzle Bonanza. Acting on consumer feedback on the original title has resulted in a new and improved puzzle game, created to satisfy real puzzle consumer requirements. Take a Break’s Puzzle Bonanza therefore retains the features that were popular in Puzzle Master and has added all-new elements - resulting in a title that not only boasts bigger puzzles, but also offers players more of a challenge and longer play duration too. Take a Break’s Puzzle Bonanza really gets to the heart of what DS puzzlers truly want.' FROM games WHERE igdb_id = 371457 ON CONFLICT (game_id, language_code) DO NOTHING;
