INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Close Combat: Last Stand Arnhem', 'Close Combat: Last Stand Arnhem is an enhanced remake of the critically acclaimed strategy game Close Combat: A Bridge Too Far by Atomic Games. In the Last Stand Arnhem you command either the Allied troops (American, British, Polish, and Dutch) as they undertake the largest airborne operation of WWII or try and half the Allied offensive as the German Army.' FROM games WHERE igdb_id = 23366 ON CONFLICT (game_id, language_code) DO NOTHING;
