INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cooking Mama World: Hobbies & Fun', 'Cooking Mama World: Hobbies & Fun gives DS owners the chance to try their hand at a variety of home crafting activities such as pottery, woodwork, jewellery design, origami and many more. Following Mama''s careful instructions, players will be shown how to create a selection of gadgets and trinkets, including a bird box, necklace, kaleidoscope, cushions and patchwork quilts.' FROM games WHERE igdb_id = 47957 ON CONFLICT (game_id, language_code) DO NOTHING;
