INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fireburst', 'Blast opponents off the road with Fireburst, an explosively fun fast-paced arcade style racing game with fantastic graphics. Rev up to scorching speeds to outrun opponents on a dozen different tracks, setting them ablaze in your flaming wake thanks to our exclusive Fireboost technology. Drive as sixteen sarcastic drivers with unique styles and taunts, using various explosive, fire-based special abilities to turn other cars into a pyre of parts. Leave opponents sucking on your smoldering dust in single-player mode, local four-player mode or the insane, firetastic online eight-player mode. Grab the wheel and burn some rubber.' FROM games WHERE igdb_id = 16343 ON CONFLICT (game_id, language_code) DO NOTHING;
