INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ghost Trick: Phantom Detective', 'Ghost Trick: Phantom Detective is a puzzle/adventure game for the Nintendo DS and iOS. It was developed mainly by Shu Takumi, the man behind the Ace Attorney Series. Game''s story centers on the protagonist Sissel, and his ghost''s struggle to discover who he was when he was alive and who killed him. The player assumes the role of this ghost, who has the ability to perform various Ghost Tricks to solve puzzles and navigate the world around him.' FROM games WHERE igdb_id = 1348 ON CONFLICT (game_id, language_code) DO NOTHING;
