INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Little Restaurant', 'In My Little Restaurant you seat your guests, collect orders, deliver meals and earn money. Every once in a while jump into kitchen and prepare some tastylicious burgers or perfect sushi. Touching, tapping and sliding fun, all with one finger and all for the whole family. Thirty-nine unique levels, extra game features, power-ups and a love story to follow. You won’t find a better deal at any other place.' FROM games WHERE igdb_id = 175487 ON CONFLICT (game_id, language_code) DO NOTHING;
