INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('submachine-universe', 129556, '2010-06-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6wrw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar18qb.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Submachine Universe', 'Submachine Universe is probably the first ever MSO (massively singleplayer online) created in 2010, extended ever since. You can freely travel between different locations, read theories about Submachine and observe how things work inside this network. There are locations that you might recognize from previous games, there''s a lot of new yet undiscovered content, there are even locations that you think you know, but they''re somehow different. Surely worth a look. The best part - it''s an open project, which means I can add more locations later on and it will all work together smoothly. So, tinfoil hats on and start exploring if you dare, because there are some dark places inside.' FROM games WHERE igdb_id = 129556 ON CONFLICT (game_id, language_code) DO NOTHING;
