INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Xenoblade Chronicles', 'Xenoblade Chronicles follows Shulk and his band of friends as they search for answers about the mysterious "Monado" sword and defend their homeland from violent robotic creatures known as the Mechon. The game contains an open world design and strongly emphasizes exploration due to the world''s large size. The game was very well received by critics, with many citing it as a great example of innovation and improvement in Japanese role-playing video games. The game has spawned a sub-series of the larger "Xeno" series, including Xenoblade Chronicles X (Wii U) and Xenoblade Chronicles 2 (Switch).' FROM games WHERE igdb_id = 2364 ON CONFLICT (game_id, language_code) DO NOTHING;
