INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Oil Blue', 'It is the future, and the world is in grave need of oil. You and a crew have set off into the ocean, reclaiming old island drilling sites for oil production as you work for the UOO, the biggest oil supplier in the world. The working conditions are dire. You have no choice.' FROM games WHERE igdb_id = 34861 ON CONFLICT (game_id, language_code) DO NOTHING;
