INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('battle-academy', 17175, '2010-08-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1qkh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/argxb.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Academy', 'Battle Academy is an action-packed tactical strategy game where you have to take command of a select group of units and lead them through battles on the many different fronts of World War II. As a commander, you will have to employ real world combined-arms tactics in order to secure victory. This means you will have to lay ambushes to surprise opposing forces, use suppressing fire to pin them, flank hostile armor for maximum effect and, if necessary, assaults the enemy to clear strong points. In some cases you will also have access to powerful off map artillery and air support with the capacity to weaken the enemy defenses or even stop an enemy attack dead in its tracks. At the same time you will have to play close attention to the morale of your own troops and use recon units to spot any hostile ambushes or flanking attacks.' FROM games WHERE igdb_id = 17175 ON CONFLICT (game_id, language_code) DO NOTHING;
