INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Air Attack', 'Take a 5 minute break to de-stress with this high-intensity, ultra simple, retro arcade shooter! Take down airplanes. Dig tunnels. Hide and seek shelter. Try and beat the highscore. That''s all. Afterwards, you will go back to your life with renewed energy of body and mind.' FROM games WHERE igdb_id = 171370 ON CONFLICT (game_id, language_code) DO NOTHING;
