INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('commander-conquest-of-the-americas', 2010, '2010-07-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2eii.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar38fi.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Commander: Conquest of the Americas', 'Combining elements from both trading and strategy games, Commander: Conquest of the Americas will appeal to a wide range of players.Players take charge of one of the many European powers aiming to conquer the New World. Starting from 16th century, players can choose from many different nations, each with their own unique strengths and weaknesses. Founding new colonies and then making them thrive is key to success. In order to accomplish this, players need to manage and optimize resources and production in their colonies, before transporting the goods to other colonies or back to Europe.Rival powers and Native Americans can prove to be allies or enemies, depending on the player decisions. Hostile fleets engage each other in highly detailed tactical level. Players can command their ships in RTS fashion or take direct control themselves.' FROM games WHERE igdb_id = 2010 ON CONFLICT (game_id, language_code) DO NOTHING;
