INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('flotilla', 8396, '2010-03-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3zr6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arova.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flotilla', 'No adventure is the same. Whenever you begin an adventure, the universe is randomly populated with characters and encounters. There is no ''up'' in space. Explore the tactical richness of full 3D movement. Watch your angles and flank the enemy from all directions. Configure your fleet. Find crazy loot throughout your adventures, and install upgrades and artifacts to your flotilla of ships. Play with a friend. Grab a buddy and play through the adventure cooperatively in splitscreen. Or, blow up your friend. In the Skirmish Mode, set up custom fleets and battle human or computer-controlled enemies.' FROM games WHERE igdb_id = 8396 ON CONFLICT (game_id, language_code) DO NOTHING;
