INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Puzzler World', 'Puzzler World brings over 1200 puzzles of 8 popular puzzle types to your PC. Conceptis picture logic puzzle fans will be happy to know that in addition to Crossword, Wordsearch, Fitword, Sudoku, Codeword, Spot the Difference and Silhouette puzzles, Puzzler World also offers 83 Conceptis Link-a-Pix available in sizes of 10x10, 20x20 and 25x25.' FROM games WHERE igdb_id = 16026 ON CONFLICT (game_id, language_code) DO NOTHING;
