INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ski Challenge 2011', 'Ski Challenge 2011 is the 7th edition of the alpine skiing series Ski Challenge. The game includes the famous alpine downhill tracks of Bormio, Val Gardena, Kitzbühel, Wengen, Val-d’Isère, Garmisch-Partenkirchen and Beaver Creek. The goal for the players is to climb the leaderboards by getting the fastest times. Three day events were held on each track to determine race winners who would win physical prizes. For the first time in the history of the series a mobile version for iOS was also available.' FROM games WHERE igdb_id = 87790 ON CONFLICT (game_id, language_code) DO NOTHING;
