INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Escape from Frankenstein''s Castle', 'Injured in a car crash with her fiancé Horatio, Hannah wakes up alone and finds herself trapped in Dr. Frankenstein’s castle. Horatio’s missing, and with guidance from a resident ghost, Isabella, Hannah quickly realizes Dr. Frankenstein is conducting strange experiments that put both her and Horatio in grave danger. Help Hannah as she interacts with the castle’s suspicious inhabitants, discovers clues about the doctor’s master plan, and completes puzzles to find a way out!' FROM games WHERE igdb_id = 213598 ON CONFLICT (game_id, language_code) DO NOTHING;
