INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Canada Hunt', 'Canada Hunt is a fully three-dimensional hunting simulation game. More realistic than any other hunting game, it features lifelike animals in their natural environments. Takes you through specialized training and bonus features that players of all levels, from the beginner to the most hardcore hunter, will enjoy. Includes ultra-realistic: Whitetail Deer, Rocky Mountain Elk, Wild Turkeys, and Critter Cam.' FROM games WHERE igdb_id = 92207 ON CONFLICT (game_id, language_code) DO NOTHING;
