INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tobarinker', 'Rare off-shoot of Ruminant Whimper''s "Hellsinker" (which is a spiritual sequel to "Radio Zonde") like D.N.A. Software''s "Shaftdiver", this is a simple single-screen action game with the goal of protecting allies and defeating bosses. It had a very small production run released back in 2010 as Trickster Jam''s first game project, the creator disappeared shortly afterwards.' FROM games WHERE igdb_id = 295431 ON CONFLICT (game_id, language_code) DO NOTHING;
