INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Exorcist', 'Remove all traces of evil spelled by supernatural powers in Exorcist, an eerie hidden object encounter. Cursed with the ability to see demons at a young age, Garret Ghostfighter uses his strange gift to help people in need. The well-known exorcist steadily continues his fight for good, until receiving a mysterious letter from someone calling himself Mephisto.' FROM games WHERE igdb_id = 54011 ON CONFLICT (game_id, language_code) DO NOTHING;
