INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Girls Life: Sleepover Party', 'Invite your friends to the coolest sleepover party ever with Sleepover Party on Wii! Sleepover Party is the interactive video game that lets you plan and host fun-filled overnight parties with your best friends. With the help of your virtual hostess Aimee, you can plan your party, choose your party theme, build your guest list, create shopping lists, and more. Then have a blast at your very own sleepover party as you play a variety of fun games and activities.' FROM games WHERE igdb_id = 50592 ON CONFLICT (game_id, language_code) DO NOTHING;
