INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shadow Fight', 'Shadow Fight was a Facebook-based fighting game developed by Nekki. It was released on February 12, 2011. In online battles, players play against each-other, utilizing magic spells, long-range weapons, and hand-to-hand combat tools, or through unarmed fighting. Shadow Fight was available on Facebook in English, Russian, German, French, Italian, Portuguese, and Turkish.' FROM games WHERE igdb_id = 61158 ON CONFLICT (game_id, language_code) DO NOTHING;
