INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '24/7 Solitaire', '24/7 Solitaire features 24 variations of the most well-known and best-loved single-player card game including Klondike, Freecell, Spider, Pyramid, Yukon and 7 versions of Peg-Solitaire. Most games have custom gameplay options so you can enjoy the game with your favourite rules. On-screen instructions allow learning of new Solitaire variations.' FROM games WHERE igdb_id = 84584 ON CONFLICT (game_id, language_code) DO NOTHING;
