INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lunar-silver-star-harmony-limited-edition', 42713, '2010-04-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co724p.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lunar: Silver Star Harmony - Limited Edition', 'Lunar, also known as the Silver Star, is a magical world brought to life by the Goddess Althena where humans live and thrive under her tender care. For countless ages since the very first human set foot on Lunar, she has dwelt among the people as a flesh and blood deity, ever protective, ever loving. With the aid of the four dragons, creatures of magic brought about by the goddess to balance the flow of magical power on Lunar, and the legendary warriors known as dragonmasters, Althena has cradled humanity from near extinction in to a thriving race once more. However, 15 years past, the last dragonmaster, Dyne, disappeared and the Goddess Althena ceased to appear among her children. Since that time the Goddess Tower has been silent and there have been no dragonmasters born unto the world. Now, during this seemingly rudderless time in Lunar''s history, one who proclaims himself the Magic Emperor has set about to bring all of Lunar''s inhabitants under his control, and only a single boy, who dreams of becoming a dragonmaster, remains to challenge him.' FROM games WHERE igdb_id = 42713 ON CONFLICT (game_id, language_code) DO NOTHING;
