INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MTV Jersey Shore', 'MTV Jersey Shore is a Facebook RPG based on the popular and controversial reality television series set in Seaside Heights, New Jersey. The game has you play as different cast members such as Snooki, the Situation, and more. The game is an online arcade-style turn-based combat, but players can also undertake a variety of activities reminiscent of the show, such as hitting the gym, tanning, doing laundry, shopping and partying, allowing them to earn coins and XP.' FROM games WHERE igdb_id = 281023 ON CONFLICT (game_id, language_code) DO NOTHING;
