INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hexyz Force', 'Hexyz Force for PlayStation Portable is a traditional RPG taking place in the world of Berge. This world has two sides to it, one light and one dark. Accordingly, the player will be able to choose between two different protagonists at the game''s beginning. In the light scenario, the protagonist is a shrine maiden by the name of Cecilia, whereas the dark part''s hero is a knight called Leevan. Depending on this choice, the setting, story and characters will change fundamentally.' FROM games WHERE igdb_id = 42884 ON CONFLICT (game_id, language_code) DO NOTHING;
