INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jig-a-Pix: Love Is...', 'JIGAPIX is an exciting range of Jigsaw Puzzle games for Nintendo DS and Nintendo DSi, providing fun for all the family and game modes to suit all ages including Free Play, Time Challenge and Wireless Multiplayer. To make things really interesting on Nintendo DSi, JIGAPIX lets you take a photo and turn it into your very own puzzle! Love is a beautiful thing! In JIGAPIX Love is … complete puzzles covering all aspects of amour with these lovable characters. 80 specially commissioned and beautifully illustrated drawings will have you puzzling for hours. Love is …, after all, also a puzzle!' FROM games WHERE igdb_id = 269784 ON CONFLICT (game_id, language_code) DO NOTHING;
