INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nu, pogodi! Vypusk 5: Po sledam zajca', 'Bully Wolf does not leave hope to catch the elusive Hare! Chasing him, the Wolf will rush through the streets and park alleys of animated Moscow, run into the stadium, where he will have to perform exercises on a variety of sports equipment, and in the end, even go out of town. Whether the hunt will succeed and whether the Wolf will be able to give a worthy rebuff to the numerous friends of the Hare depends on the player''s ingenuity and speed of reaction.' FROM games WHERE igdb_id = 232863 ON CONFLICT (game_id, language_code) DO NOTHING;
