INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kataribesou: Ensouki', 'Kataribesou: Ensouki is a game inspired by Yume Nikki, starring a featureless figure named Shidonoko, traveling into weird worlds from a building. The game contains RPG elements (combat, an item shop, etc.). It additionally lets one choose a difficulty level at the start of the game.' FROM games WHERE igdb_id = 229386 ON CONFLICT (game_id, language_code) DO NOTHING;
