INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'CSI: Unsolved', 'Specifically designed with Nintendo DS users in mind, CSI: Crime Scene Investigation: Unsolved! makes the most of the Nintendo DS Touch Screen for an improved pick-up-and-play experience. Players get to join forces with their favorite CSI characters from the hit CBS show and solve five original murder mysteries, such as the death of a young pop star on stage or the discovery of a mummified body in the desert.' FROM games WHERE igdb_id = 47796 ON CONFLICT (game_id, language_code) DO NOTHING;
