INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Utacchi', 'Utacchi is a rhythm video game developed and published by Konami for the Nintendo DS in 2010. It was released exclusively in Japan under the Pop''n Music series. The game plays with the system held in "book style" as the player interacts with falling notes using the stylus. The name ''Utacchi'' is a portmanteau of the Japanese words "uta", meaning ''song'', and "tachi", a loan word from English meaning ''touch''.' FROM games WHERE igdb_id = 80482 ON CONFLICT (game_id, language_code) DO NOTHING;
