INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bibi & Tina: Die große Schnitzeljagd', 'Bibi and Tina are best friends and Bibi spends almost every holiday at Tina''s mother''s horse farm. There the girls experience exciting adventures, help out on the farm and feed the horses. This time, Tina''s brother Holger came up with something special for Bibi and Tina: he organized a scavenger hunt. On horseback, of course - and so it''s not just about solving the tasks at the individual stations with skill, but also taking care of the needs of the horses.' FROM games WHERE igdb_id = 216188 ON CONFLICT (game_id, language_code) DO NOTHING;
