INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('saw-ii-flesh-blood', 7177, '2010-10-19', 73, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3izx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scegoz.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saw II: Flesh & Blood', 'The demented serial killer Jigsaw returns with more gruesome torture puzzles designed to test the limits of human ethics in Saw II: Flesh & Blood. Set between the second and third Saw films, Flesh & Blood puts players in the shoes of Michael, son of the first game''s protagonist Detective David Tapp, as he looks for clues as to his father''s death and becomes the latest target of Jigsaw and his strange apprentice Pighead II. The gameplay once again mixes heavy doses of survival horror and puzzle-solving with mild combat elements, as players attempt to help themselves, and others, out of life-and-death situations by successfully completing mini-games and quick-time events. The combat comes in two forms, with gamers using melee attacks and a variety of weapons in physical battles against Jigsaw''s thugs, or executing puzzle-based attacks that make use of traps and environmental hazards. Various case files are strewn about the hotels, factories, and sewers in which the game is set, and players can also collect a number of Billy the Puppet dolls hidden throughout each level. As was the case with its predecessor, Saw II: Flesh & Blood includes multiple endings based on choices gamers make throughout the story.' FROM games WHERE igdb_id = 7177 ON CONFLICT (game_id, language_code) DO NOTHING;
