INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tommy Tronic', 'Tommy Tronic - an old-skool platformer that isn''t trying to be anything else! Jumping, shooting, dodging and exploring is all that''s required to help get Tommy to his destination and free his tiny puppy from the clutches of an insane genius school-kid and his brutal sidekick ''Biffa''. It would be straight forward too, if it wasn''t for the fact that this journey will take Tommy through Gnarly wood; a twisted and eerie forest that adults avoid let alone tiny children! Imagination runs amok as Tommy confronts his childish fears head on, all in a bid to be reunited with his beloved pal ''Yapz''.' FROM games WHERE igdb_id = 15010 ON CONFLICT (game_id, language_code) DO NOTHING;
