INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Road Fighters 3D', 'Road Fighters is a 3D racing game from Konami. The game is a sequel to Konami''s first driving game, Road Fighter which was released in 1984. The cabinet has a set of 3D glasses mounted to the machine and two ''peep-holes'' built into the seat to allow spectators to view the action in 3D also. Players can also play the game in 2D and can switch between 2D and 3D modes with the press of a button.' FROM games WHERE igdb_id = 124285 ON CONFLICT (game_id, language_code) DO NOTHING;
