INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hannibal: Rome and Carthage in the Second Punic War', 'Hannibal: Rome and Carthage in the Second Punic War is a new and innovative turn-based strategy game that puts you in command of the Carthaginian military during a period of total war over land and sea with the young Roman Republic. With this military juggernaut of the ancient world at your disposal, you will vie for control over Italy, Carthage, Spain and the Mediterranean Sea using a combination of strategic political maneuvering and sheer tactical skill both on land and sea.' FROM games WHERE igdb_id = 129583 ON CONFLICT (game_id, language_code) DO NOTHING;
