INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tales of the Drunken Paladin', 'Tales of the Drunken Paladin is a fantasy-comedy RPG about a universally disliked hero who very suddenly loses absolutely everything - including his identity - and must go on a quest to find out who''s responsible. It''s also largely a game about interacting with thousands of inanimate objects. One full playthrough is between 40-60 hours. Once you''ve beaten the game, hard mode is unlocked.' FROM games WHERE igdb_id = 191811 ON CONFLICT (game_id, language_code) DO NOTHING;
