INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'HTR High Tech Racing', 'High Tech Racing is a Slot Car Racing Simulator, a virtual version of the classic toy of the 80s and 90s. HTR offers 3 different difficulty levels and 18 tracks that include several challenges like loops, jumps, crossroads, narrows, and high-speed curves. You can even build your own tracks with the highly intuitive Track Editor. Choose from 3 in-game visualization modes, from a 3rd-person perspective to an in-car camera.' FROM games WHERE igdb_id = 85174 ON CONFLICT (game_id, language_code) DO NOTHING;
