INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Princess Isabella: A Witch''s Curse', 'The game begins with Princess Isabella returning home from a trip to discover that an evil curse has been put upon her castle. The curse has placed evil in every room and turned everyone inside the castle into mirrors. With the help of a fairy friend, players must step into Princess Isabella''s shoes and battle against an evil witch to lift the curse.' FROM games WHERE igdb_id = 51002 ON CONFLICT (game_id, language_code) DO NOTHING;
