INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Het Huis Anubis: Het geheim van Osiris', 'The residents of The House of Anubis need your help! This adventurous game takes you to an abandoned inn, a beautiful garden full of ancient artifacts, and even to distant Egypt. You embark on a miraculous journey through time and find yourself in the world of the original inhabitants of the House of Anubis: the Winsbruggen-van Hennegouwen couple and their daughter. Can you solve the puzzles, find the treasures, and uncover the Secret of Osiris?' FROM games WHERE igdb_id = 330105 ON CONFLICT (game_id, language_code) DO NOTHING;
