INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'AssaultCube Reloaded', 'AssaultCube Reloaded is a free-and-open-source first-person-shooter aimed at improving its predecessor, AssaultCube. This game combines the best of all worlds. Realism from Battlefield, anti-cheat from the Quake engine, perks from Call of Duty, and fast-paced gameplay with a low system footprint from AssaultCube.' FROM games WHERE igdb_id = 130611 ON CONFLICT (game_id, language_code) DO NOTHING;
