INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Darkfate', 'Darkfate is an exploration platformer that follows Chris Freeman, a man whose memory has failed him. He has no idea why he’s wandering around a snowy mountainside in freezing weather and decides to venture into nearby caves to seek out answers. During his odyssey, he keeps a record of his thoughts in a journal.' FROM games WHERE igdb_id = 242817 ON CONFLICT (game_id, language_code) DO NOTHING;
