INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Art Academy', 'Art Academy offers simple, easy to understand art lessons that you can take at your own pace. You even have the ability to fast forward or rewind a step if you would like to view it again. Vince is your in-game art tutor and he will guide you through each new lesson, gradually introducing new concepts to you. Each new lesson builds upon concepts that you learned in previous lessons, complete with step by step examples.' FROM games WHERE igdb_id = 22959 ON CONFLICT (game_id, language_code) DO NOTHING;
