INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Halo: Reach - Legendary Edition', '“Halo: Reach” tells the tragic and heroic story of Noble Team, a group of Spartans, who through great sacrifice and courage saved countless lives in the face of impossible odds. The planet Reach is humanity’s last line of defense between the encroaching Covenant and their ultimate goal, the destruction of Earth. If it falls, humanity will be perched on the brink of destruction.' FROM games WHERE igdb_id = 43954 ON CONFLICT (game_id, language_code) DO NOTHING;
