INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Playmobil: Circus', 'In Playmobil Circus, you and your family are going to become Playmobil performers in the funniest, most wacky circus around. Practice your acts to make sure they''re perfect before you perform them in the center ring for the whole crowd. Perform well enough you''ll unlock more acts in Encore mode. Play with friends and family in 2 exciting multiplayer modes: co-op and versus.' FROM games WHERE igdb_id = 20319 ON CONFLICT (game_id, language_code) DO NOTHING;
