INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pocket Legends', 'Pocket Legends is the first "real" western cross-platform mobile MMORPG for the iOS and Android platforms, designed by Spacetime Studios. Pocket Legends takes place in a land called Alterra, where "forces of evil" are attacking the kingdom. The Elf Queen calls upon the help of the animal inhabitants to assist in defeating the intruders, which brings the premise for the gameplay. Due to the pick up and play mentality of the game, it is not as story driven as PC or console-based MMORPGs.' FROM games WHERE igdb_id = 22969 ON CONFLICT (game_id, language_code) DO NOTHING;
