INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SFG Soccer', 'Over-the-top arcade soccer action! Bicycle kicks, headers, one-touch passes, slide-tackles, instant replays, it''s all here. New enhancements include mouse controls, and a two-button ''Casual Mode'' for more laid back gamers. An RPG-style leveling system is used for the multi-season Career Mode featuring 64 teams from around the world. Play co-op or solo as you lead your team all the way up to the Division 1 Championship Game!' FROM games WHERE igdb_id = 66700 ON CONFLICT (game_id, language_code) DO NOTHING;
