INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Casual Mania!', 'Feed your addiction with Casual Mania - four of the world''s most popular games now available to play on your Nintendo DS. Play Hidden Objects and search for items at an excavation site under the Louvre. In the game 3 in a Row, you need to collect three or more of the same gems. Marble Popper challenges you to put together combinations of at least three colored balls. Or run a french beauty salon in the hectic time management game of Beauty Resort.' FROM games WHERE igdb_id = 206903 ON CONFLICT (game_id, language_code) DO NOTHING;
