INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Advanced Circuits', 'Whether with a train, a car or a tank, are you ready for a new challenge? This brain-boggling puzzle game will put your powers of deduction to the test. Complete the circuits by connecting squares on the game board with pieces of track. Some pieces of track are already shown on the board at the beginning of the game to give you a head start. There is only one solution to each puzzle. The rules are simple but the challenges are tough.' FROM games WHERE igdb_id = 84973 ON CONFLICT (game_id, language_code) DO NOTHING;
