INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('storybook-workshop', 50975, '2010-01-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/xgk5cjwzccp0g20ssd0k.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Storybook Workshop', 'Storybook Workshop immerses kids and their parents in 16 classic children''s fairy tales and fables and many other exciting features. Through the use of the included USB microphone, you can read along, record and play back readings of your favorite stories, including the most beloved tales from Hans Christian Andersen, the Brothers Grimm, Aesop and around the world. Storybook Workshop''s unique microphone functionality will even magically change your voice to sound like the characters in the stories, including fairies, giants and robots! Continue the fun with your children in a lively sing-along room where nursery rhymes come to life right in front your children''s eyes, and watch as they learn rhythm, language, numbers and shapes in the exciting Play & Learn mode. Your kids can track their progress by using a virtual sticker pad, which will get pre-schoolers excited and motivated to continue to read and complete the stories.' FROM games WHERE igdb_id = 50975 ON CONFLICT (game_id, language_code) DO NOTHING;
