INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Treasure Chase', 'The challenging thinking game goes to the next level. Take a trip to exotic places around the world and find extraordinary treasures of human history. More than 300 demanding puzzles on 16 different maps await you. New gaming pieces such as snakes, switches and ice stones make "Know How 2" even trickier. With a freely rotatable playing area and the option of undoing your moves as often as you want, you will always have an overview of the current state of play.' FROM games WHERE igdb_id = 47713 ON CONFLICT (game_id, language_code) DO NOTHING;
