INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mugen no Frontier: Super Robot Taisen OG Saga - Exceed', 'Super Robot Taisen OG Saga: Endless Frontier Exceed is a crossover role-playing video game. Players take control of a party of characters drawn from multiple anime and video game franchises. Gameplay is divided between field navigation, dialogue sections between characters, and turn-based battles where players can expend action points to perform different moves.' FROM games WHERE igdb_id = 124069 ON CONFLICT (game_id, language_code) DO NOTHING;
