INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Petz: Hamster Superstarz', 'Adopt your very own family of hamsters! Care for them, teach them fun tricks and unlock new toys and accessories to give them lots of love! Care for your hamsters by feeding them, playing with them and keeping them clean and warm. Discover your hamsters'' unique personalities - watch them react with cute and funny facial expressions. Teach your hamsters fun activities like bowling or running on ramps and watch them progress. Earn coins that can be used to unlock new toys and accessories for your lovable hamsters.' FROM games WHERE igdb_id = 47972 ON CONFLICT (game_id, language_code) DO NOTHING;
