INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bass Pro Shops: The Hunt', 'The Hunt drops players into the wilderness of North America''s most famous hunting locations where players will be able to stalk and hunt their prey using a variety of different firearms-bolt-action rifles, shotguns, pistols, bows, and knives. To help them in their hunt they will use Bass Pro Shops gear and equipment like calls, scents, stands and a uniquely designed GPS to guide the player to the action. The Hunt features three game modes: Quick Hunt, Career Mode, and the Bass Pro Shops Continental Classic Hunting Championship as well as four mini-games (Target Range shooting, ATV Racing, Blind Fire, and Coyote Cruise).' FROM games WHERE igdb_id = 51049 ON CONFLICT (game_id, language_code) DO NOTHING;
