INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fantastic Football Fan Party', 'Get ready for a Fantastic Football Fan Party and explore the excellent party fun based around the beautiful game and its fans. Battle for countless trophies and bragging rights…right in the middle of your living room! Create your own player, in any style you like. Unlock countless additional funky items to pimp up your character! Become a lightning quick winger…or an outstanding acrobatic goal scorer. Get the crowd pumped by drumming them into a frenzy! Show off your extraordinary ball juggling skills, score unbelievable goals in a fast-paced shoot out and dodge crazed fans as you celebrate your victory! Have your own Fantastic Football Fan Party at home and show how football you are! Key Features: - Experience 10 fun-filled party games based around the beautiful game and ist fans! - Create your own player, in any style you like. - Unlock countless additional funky items to pimp up your character - Battle for countless trophies and bragging rights - Go crazy with multiplayer fun for up to four players - Enjoy excellent party fun for the whole family' FROM games WHERE igdb_id = 268130 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 268130 AND p.igdb_id = 5 ON CONFLICT DO NOTHING;
