INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yume, Shosen Mousou', 'Yume, Shosen Mousou is a Yume Nikki fangame. It stars Kamitsuki, who not only refuses to leave their room, but blocks the door. It plays like most fangames, the main objective being to collect all 22 effects to unlock the ending. Also, this game has no background music, although sound effects are fully present.' FROM games WHERE igdb_id = 150172 ON CONFLICT (game_id, language_code) DO NOTHING;
