INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TNT Racers', 'TNT Racers is a racing video game for the Wii U, Wii, PlayStation 3, PlayStation Portable, and Xbox 360. The game was released on the consoles as downloadable games. The game was developed by dtp entertainment for the WiiWare and PSP games, while Keen Games developed the PS3 and Xbox Live Arcade versions. The game was released on December 1, 2010 for the PS3, February 9, 2011 for the Xbox 360, and March 31 for the Wii and PSP.' FROM games WHERE igdb_id = 20555 ON CONFLICT (game_id, language_code) DO NOTHING;
