INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hidden Mysteries: Salem Secrets', 'Help Constable Hawthorne investigate the rumors of witchcraft in Hidden Mysteries – Salem Secrets, a fun Hidden Object Puzzle Adventure game! Four young girls have been suffering from an outbreak of mysterious fits and bizarre tantrums. Rumors abound that the girls have been "afflicted" by local practitioners of Witchcraft, but nobody has yet been charged or tried. Investigate the scenes and uncover the Hidden Mysteries!' FROM games WHERE igdb_id = 66193 ON CONFLICT (game_id, language_code) DO NOTHING;
