INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zhu Zhu Pets', 'Zhu Zhu Pets are innovative, realistic, interactive, plush, and artificially intelligent hamsters that talk and move around in their own playsets. Zhu Zhu Pets include two play modes: nurturing mode where the hamsters coo and purr and adventure mode where the hamsters explore their habitat with intelligent audio and mechanical responses to various habitat stimuli. Over a dozen add-ons can be purchased to build an ever-evolving hamsterworld for your hamster to play in and explore.' FROM games WHERE igdb_id = 9168 ON CONFLICT (game_id, language_code) DO NOTHING;
