INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mishap: An Accidental Haunting', 'The Burtons have just moved into their beautiful new dream home, which unfortunately for them, happens to be haunted. As they prepare to pack up and leave, they are suddenly greeted by the peculiar Milton Hobblepop, self described paranormal investigator. Now the Burtons need your help to clear their house of a group of particularly unfortunate ghosts. Enter the domains of these eccentric specters and search for objects hidden throughout over 30 beautifully illustrated rooms.' FROM games WHERE igdb_id = 16162 ON CONFLICT (game_id, language_code) DO NOTHING;
