INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Treasures of Mystery Island 2: The Gates of Fate', 'Embark on an all-new adventure in The Treasures of Mystery Island 2: The Gates of Fate. When the Gates of Fate send Alex and Lisa back in time, each to a different decade, they must figure out how to return to the present, and each other, before a rumbling volcano spews its contents. Guide Lisa as she befriends a local girl, searches for the magic tiles that can send her home, and leaves clues for Alex to find in the future. Then help Alex save himself before it''s too late.' FROM games WHERE igdb_id = 53773 ON CONFLICT (game_id, language_code) DO NOTHING;
