INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ferrari-the-race-experience', 22953, '2010-10-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co74la.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ferrari: The Race Experience', 'From the creators of Ferrari Challenge comes a brand new Ferrari racing extravaganza; Ferrari The Race Experience! This amazing new racer features the definitive Ferrari collection which includes such greats as the GTO, the Enzo, the 599XX and the stunning new 458 Italia! The game also features a selection of difficulty settings as well as three car handling settings – Assisted, Arcade and Simulation – so that absolutely everyone can enjoy the feel of a Ferrari. A three-tiered Career mode allows you to split your time across Classics cars, Road cars and GT cars, with each allowing you to earn all-important Credits for the Showroom. Use your money to buy new cars and then customize the colour and design to your own specifications before showing your creations off in the game’s 1-16 player LAN and online multiplayer mode! This truly is the ultimate in Ferrari race experiences!' FROM games WHERE igdb_id = 22953 ON CONFLICT (game_id, language_code) DO NOTHING;
