INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'EpicWin', 'EpicWin is an iPhone app that puts the adventure back into your life. It’s a streamlined to-do list, to quickly note down all your everyday tasks, but with a role-playing spin. So rather than just ticking off your chores and reminders, completing each one earns you XP to improve and develop your character in an ongoing quest to improve stats, gain riches, and level-up.' FROM games WHERE igdb_id = 175469 ON CONFLICT (game_id, language_code) DO NOTHING;
