INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gaia Attack 4', 'Gaia Attack 4 is a 4 player light gun shooter from Taito, released in 2010 and running on their Taito Type X2 hardware. Users play as ''Ghostbusters'' whose goal is to kill as many ghosts and aliens as possible. The game features video footage of real world environments, overlaid with cartoon computer images of aliens, creatures and more.' FROM games WHERE igdb_id = 64962 ON CONFLICT (game_id, language_code) DO NOTHING;
