INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ZooMumba', 'ZooMumba was a free-to-play zoo simulator developed and published by Bigpoint where players took up the responsibility of creating and maintaining a zoo. Players started with an empty piece of land to transform into a successful zoo. Players had a variety of objects and tools at their disposal to transform the empty piece of land into one of the world’s best zoos. As of July 2018, there were over 17,150,000 registered users of the game, and it was available in 26 different languages.' FROM games WHERE igdb_id = 304277 ON CONFLICT (game_id, language_code) DO NOTHING;
