INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Heritage', 'The year is 1916. To escape from war, and protect your daughter, you must go to your Grandfather''s haunted old manor! The local inhabitants of a nearby village tell stories about the ghosts and the terrible things inside the mansion, but you have no choice! Explore the old house as you discover The Heritage of your family and uncover incredible secrets in this fun and immersive Hidden Object game.' FROM games WHERE igdb_id = 54303 ON CONFLICT (game_id, language_code) DO NOTHING;
