INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alien Zombie Death', 'Somewhere far far away in a random solar system, a lone space man dies... horribly. Take control of said fateful space man as he battles to his end against the dreaded Alien Zombies! Using a standard laser gun and a few pickups along the way, make sure you take out as many of those Alien Zombie suckers before they take you down. Its that simple. It''s Alien Zombie Death.' FROM games WHERE igdb_id = 15189 ON CONFLICT (game_id, language_code) DO NOTHING;
