INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dynasty Warriors: Gundam 3', 'First released in December 2008, the Dynasty Warriors: Gundam series has gained much popularity, and finally the newest entry is going to be released soon. By continuing all of the popular elements and loosing unpopular elements of the previous installments, we hope that this installment is the best of the series. With newly added features to set this installment apart from the rest, it has evolved to increase the player''s sense of "an authentic battlefield experience."' FROM games WHERE igdb_id = 6982 ON CONFLICT (game_id, language_code) DO NOTHING;
