INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Imagine: Sweet 16', 'It''s your sixteenth year and you''ve just joined a new high school. How will you become the girl to know? By planning, promoting and hosting the most awesome Sweet Sixteen ever -- including your own. Select your party’s theme and decorations, plan fun activities for your guests, and pick the right music to keep the party going all night long!' FROM games WHERE igdb_id = 5989 ON CONFLICT (game_id, language_code) DO NOTHING;
