INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ZombieSmash HD', 'ZombieSmash HD is a survival comedy game, featuring undead-themed castle defense and entertaining, physics-based gameplay. The game casts players as Joey, a lone survivor pit against a herd of writhing, unrelenting zombies. To defeat the undead masses, players must use their fingers to flick and smash them until they’re un-undead.' FROM games WHERE igdb_id = 281446 ON CONFLICT (game_id, language_code) DO NOTHING;
