INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nightshift Legacy: The Jaguar''s Eye', 'Nightshift Legacy takes you on a historical adventure full of romance and intrigue with The Nightshift Code heroes, Mike and Isabel. You''ll travel from the jungles of Guatemala to the streets of Moscow, from present day back to the history of the Spanish Civil War, brush elbows with historical luminaries such as Frida Kahlo and Diego Rivera while hunting for stolen artifacts across multiple continents. Can you find the mysterious Jaguar''s Eye before it''s too late?' FROM games WHERE igdb_id = 16077 ON CONFLICT (game_id, language_code) DO NOTHING;
