INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hellkid: Hook & Jump', 'HellKid is at its core a conventional 2D side-scrolling platform game, but with a lot of added twists and features. As Devi, your objective is to collect enough souls in your quest to become human! Souls come in various colors such as golden and blue, and each of the 12 levels in "Valley of Soul" with increasing difficulty contains more than 50 patterns to master.' FROM games WHERE igdb_id = 184071 ON CONFLICT (game_id, language_code) DO NOTHING;
