INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cart Life', 'Cart Life is a retail simulation for Windows which showcases the lives of street vendors in a small city which is located in the Western United States. In the game the player controls one of three street vendors, and attempts to run their shop whilst looking after their health, interests, and families. Each of the playable characters has specific goals and special traits, but also unique addictions which the player must accomodate in order to succeed within the game.' FROM games WHERE igdb_id = 50179 ON CONFLICT (game_id, language_code) DO NOTHING;
