INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SingStar: Chart Hits', 'SingStar is a karaoke game exclusively released in Australia and New Zealand. It includes pop songs by international and Australian artists. There are no gameplay changes: player(s) sing into a microphone and the game gives points based on the performance. The only basis of assessment is if the correct note is hit with the correct timing; the sung words or octave does not play into the result.' FROM games WHERE igdb_id = 15192 ON CONFLICT (game_id, language_code) DO NOTHING;
