INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Irekae Maho-chan', 'Irekae Maho-chan is a puzzle platform game where the player controls the young girl Maho-chan, who has the curious ability to swap places with other creatures. She does this by throwing rainbow stars at them, and must use this ability to pass through walls in order to reach the exit door of each stage. Green walls can be shot through, while purple walls are solid and will block Maho-chan''s exchange stars. There are a total of 50 stages, most of which have a very strict time limit, but the player can choose any stage to start or continue from.' FROM games WHERE igdb_id = 66280 ON CONFLICT (game_id, language_code) DO NOTHING;
