INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Prison Break: The Conspiracy', 'Prison Break: The Conspiracy follows Company agent Tom Paxton, who infiltrates Fox River prison to monitor Michael Scofield''s rescue attempt of his wrongly convicted brother Lincoln Burrows. Running parallel to the first season of the TV series, this stealth-action game has players navigating prison grounds while avoiding detection from guards and hostile inmates. Players complete various missions involving surveillance and infiltration, with the option to engage in hand-to-hand combat when confronted by other prisoners. Between missions, Paxton can participate in prison activities such as weightlifting, getting tattoos, and participating in organized fights for rewards.' FROM games WHERE igdb_id = 557 ON CONFLICT (game_id, language_code) DO NOTHING;
