INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A House in California', '‘A House in California’ is a surreal, narrative game about four characters who bring a house to life. These four characters are based on relatives of mine (two grandmothers and two great-grandmothers). The game is inspired aesthetically by Mystery House, developed in 1980 by Roberta & Ken Williams. But whereas Mystery House is a mystery story about greed and murder, A House in California is more like an Imagist poem about family and memory.' FROM games WHERE igdb_id = 60457 ON CONFLICT (game_id, language_code) DO NOTHING;
