INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Camp Rock: The Final Jam', 'Create and play as your very own rocker and join Mitchie, Shane and other Camp Rockers back at the music camp! Meet some new campers as you explore the camp and help them out as they go against their rival Camp Star. Rock out to songs from both Camp Rock films using your stylus to play guitar, bass, and drums. You can even put down some hot dance moves wearing cool outfits for your avatar.' FROM games WHERE igdb_id = 122508 ON CONFLICT (game_id, language_code) DO NOTHING;
