INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eclipse', 'Eclipse is a psychological horror game inspired by Silent Hill, Clock Tower, and Ravenwood Horror. You play as a lone protagonist navigating a surreal and terrifying world filled with traps, illusions, and emotional tension. The game features handcrafted maps, branching dialogue, and a ranking system introduced in later versions. With a haunting atmosphere and layered storytelling, Eclipse challenges players to confront fear and unravel the mystery behind Mist Valley Hospital.' FROM games WHERE igdb_id = 295243 ON CONFLICT (game_id, language_code) DO NOTHING;
