INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cats-and-dogs-the-revenge-of-kitty-galore', 152609, '2010-07-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3add.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cats & Dogs: The Revenge of Kitty Galore', 'In Cats & Dogs: The Revenge of Kitty Galore, players fight Kitty Galore''s agents of evil to save the day and send the bad guys packing. Players will have to utilize their animalistic acrobatics and AI "Animal Intelligence" to make their way through various levels and obstacles and collect critical items and power-ups, which will unlock new areas as they progress through the game. They will also be challenged by a number of covert missions including helping stool pigeons carry out their air-based special operations and destroying Kitty Galore''s treacherous equipment. Featuring six different mission types, including escort, stealth and combat, the game promises to deliver on all the excitement of the film, leading to the big showdown with Kitty Galore.' FROM games WHERE igdb_id = 152609 ON CONFLICT (game_id, language_code) DO NOTHING;
