INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic Free Riders', 'Jump into the race! Become your favorite Sonic character and use your whole body to twist, turn and jump in this hi-octane game exclusive to Kinect. Crouch and jump to pull huge airs! Ride boards, bikes, jet skis, and even a mine cart! Take out competitors with crazy weapons!' FROM games WHERE igdb_id = 20118 ON CONFLICT (game_id, language_code) DO NOTHING;
