INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Schlag den Raab', 'Have you always wanted to get a taste of the original TV atmosphere and feel what it''s like to be a contestant on Germany''s most popular TV show? No problem, because Schlag den Raab makes it possible! Compete against Stefan Raab and try to show the ambitious host who is better in terms of skill, knowledge and action.' FROM games WHERE igdb_id = 69474 ON CONFLICT (game_id, language_code) DO NOTHING;
