INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Iron Man 2', 'Iron Man 2 is a 2010 action-adventure video game loosely based on the film of the same name. The game has an original story written by The Invincible Iron Man scribe Matt Fraction. This story is set after the plot of the film, although the iOS and BlackBerry versions stick roughly to the film''s plot. The game features the voices of Don Cheadle and Samuel L. Jackson, reprising their roles from the film.' FROM games WHERE igdb_id = 200998 ON CONFLICT (game_id, language_code) DO NOTHING;
