INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gundam Assault Survive', 'Gundam Assault Survive is the fifth game in the Gundam Battle series. Unlike its predecessors, it expands beyond the Universal Century and into Gundam series from alternate universes. Mobile Suit Gundam F91, Mobile Suit Gundam SEED and the first season of Mobile Suit Gundam 00 all become part of the campaign, while Mobile Suit Victory Gundam contributes MS. The game was released on March 18, 2010 in Japan.' FROM games WHERE igdb_id = 67126 ON CONFLICT (game_id, language_code) DO NOTHING;
