INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gourmania 3: Zoo Zoom', 'Patch things up between Victoria and her estranged father in Gourmania 3 - Zoo Zoom, a generous third helping of hidden object cooking fun. Victoria is living a socialite''s life with expensive clothes and a pampered pet, all paid for by her father. When dad decides to cut off her money stream so that she may learn five important family virtues, she has no choice but to accept.' FROM games WHERE igdb_id = 54067 ON CONFLICT (game_id, language_code) DO NOTHING;
