INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zeno Clash: Ultimate Edition', 'A first-person action/fighting game set in a punk fantasy world, players assume the role of Ghat, the son of a creature called Father-Mother whose children make up the strongest clan in the city of Halstedom. Ghat escapes from his family and sets out on journery across the land with his female companion Deadra, discovering more of the world and his past along the way.' FROM games WHERE igdb_id = 21578 ON CONFLICT (game_id, language_code) DO NOTHING;
