INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bomberman: Disney Stitch Edition', 'Bomberman: Disney Stitch Edition was an action game developed by Hudson Soft and published by D2 Communications and released on mobile phones in August 2, 2010 in Japan. It features the Bomberman gameplay and the visuals of Disney''s Lilo & Stitch franchise, more specifically the Stitch! anime series, with the alien Stitch as the playable character and the game is a timed score attack challenge.' FROM games WHERE igdb_id = 198061 ON CONFLICT (game_id, language_code) DO NOTHING;
