INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kitsu Saga', 'Kitsu Saga was a free-to-play 3D fantasy MMORPG developed by X-Legend and published by Aeria Games. The game featured conventional MMO trappings including many quests and a variety of mounts, but what set Kitsu Saga apart were the multiple-character ages where players could adventure as either children or adults, and the ability to fight along the Kitsu, fox-like creatures. The game was shut down in July of 2011.' FROM games WHERE igdb_id = 98813 ON CONFLICT (game_id, language_code) DO NOTHING;
