INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('witches-and-vampires-the-secrets-of-ashburry', 47813, '2010-12-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/nhmowzmqg6c0pbu7oocg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/tebn0qvbykknirlmwgbg.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Witches & Vampires: The Secrets of Ashburry', 'Witches & Vampires is an adventure game that tells the story of three magical half siblings and their struggle against evil.Three supernatural siblings work together to fight demons and vampires in this role-playing game from Conspiracy Entertainment. Play as witch Aluna, vampire Dariel, and half-blood Ruby as they search the village of Ashburry for the six mystical amulets needed to stop the evil creatures. Players can interact with townsfolk to receive quests and venture into dungeons to hunt for treasure and clues to the missing amulets. The touch-screen interface is used to perform actions such as casting spells, digging for treasure, and more. Also included are various mini-games, such as flying on a broomstick through a series of floating rings.' FROM games WHERE igdb_id = 47813 ON CONFLICT (game_id, language_code) DO NOTHING;
