INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lucha Libre AAA: Héroes del Ring', 'Lucha Libre AAA: Héroes del Ring is an action sports game based on Mexican sport of ''Lucha Libre'' style wrestling. Featuring all of the most popular ''luchadores'' from Mexico''s premiere wrestling federation, the game offers fans of existing wrestling franchises an evolved and unique gaming experience which is more acrobatic and fast-paced than those of existing wrestling franchises.' FROM games WHERE igdb_id = 7060 ON CONFLICT (game_id, language_code) DO NOTHING;
