INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heathcliff: The Fast and The Furriest', 'Alien cat-like creatures have spent an eternity travelling through space, looking for a new place to call home, and have landed just outside Heathcliff''s hometown! They abduct Sonja, and demand Heathcliff win a racing challenge to get her back.' FROM games WHERE igdb_id = 24375 ON CONFLICT (game_id, language_code) DO NOTHING;
