INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Need for Speed: Hot Pursuit - Limited Edition', 'The Need for Speed Hot Pursuit Limited Edition delivers six exotic cars; Alfa Romeo 8C Competizione, Ford Shelby GT500, Audi TT RS Coupé, Chevrolet Camaro SS, Porsche Cayman S and Dodge Challenger SRT8. The Alfa Romeo 8C Competizione and Ford Shelby GT500 are only available in the Limited Edition – and will not be available at any other time.' FROM games WHERE igdb_id = 21696 ON CONFLICT (game_id, language_code) DO NOTHING;
