INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hello Kitty Seasons', 'Hello Kitty Seasons will challenge players to create a character and direct the development of a colorful town populated by lovable Sanrio characters such as Hello Kitty, My Melody, Keroppi, Badtz-Maru, Little Twin Stars and Chococat. Players will build up the community around them to unlock new levels and a variety of adventures while playing fun and exciting mini games that challenge their Wii Remote skills. Along the way, players will customize their town, earn achievements, discover bonuses and unlock power-ups. As time passes, the game world changes to reflect the player''s actions and the turning of the seasons, with each season presenting its own challenges and opportunities.' FROM games WHERE igdb_id = 25191 ON CONFLICT (game_id, language_code) DO NOTHING;
