INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SingStar: Fussballhits', 'SingStar: Fussballhits is a karaoke game, featuring popular soccer songs. The game gives points which are distributed by the purity of singing, as in how well does one manage to stay on tune. It does not matter if you change octaves in the middle of the song or what words are you singing in as it does not have word recognition, so your singing is rated by how well you manage to hit the correct note at the correct time.' FROM games WHERE igdb_id = 98692 ON CONFLICT (game_id, language_code) DO NOTHING;
