INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fight Ippatsu! Juuden-Chan!! CC', '“Fight Ippatsu! Juuden-Chan!! CC” is an adventure game based on the TV anime based on the original work by Mr. Jitama. The game revolves around the original character "Cell" (CV: Eri Kitamura) created by Mr. Jitama, and includes full voices by the same cast as the TV anime. We use multiple stories and multiple endings, where the story changes depending on which characters you become friends with.' FROM games WHERE igdb_id = 278831 ON CONFLICT (game_id, language_code) DO NOTHING;
