INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bowling-3d', 42776, '2010-01-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7yqp.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bowling 3D', 'Take the sensation of hitting the lanes to another dimension with Bowling 3D for PSP. You might even feel like you need to rent some shoes. See the alley spring to life in multiple immersive 3D environments. Then experience an extra dimension of authenticity with the game''s innovative physics and mechanics. Control the ball''s direction and the force behind your stroke. Use the Spin Meter to add action. Find your groove with strike after strike, or finess your shot for a clutch spare. Challenge up to four friends with a variety of Pass ''n Play modes. Or bwol like a pro in five single-player modes, including Quick Play, Spare-O-Thon, and the exclusive Strike-O-Thon. Between frames, watch replays of your slickest shots from up to five angles. Track stats, earn achievements, and win awards.' FROM games WHERE igdb_id = 42776 ON CONFLICT (game_id, language_code) DO NOTHING;
