INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Suzunone Seven!', 'There is a prestige school called Suzunone Magic School in the world where magic is established as one of the energies. However, the school has some dropout students. The worst seven students are forced to take part in a studying camp called Suzunone Trial. They take exams and they will be dismissed from school if they fail. It''s time to decide the worst seven again...' FROM games WHERE igdb_id = 62265 ON CONFLICT (game_id, language_code) DO NOTHING;
