INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cities XL 2011', 'Imagine and conceive cities of all types and sizes on Cities XL planet. From a several million citizens megalopolis to a hyped seaside resort, to an industrial city, everything is allowed in Cities XL 2011! Take advantage of an incredible collection of more than 700 buildings and structures, 47 different types of maps featuring realistic environments. Enjoy never seen before freedom in a city-builder!' FROM games WHERE igdb_id = 2154 ON CONFLICT (game_id, language_code) DO NOTHING;
