INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Millionaire City', 'In Millionaire City you are in charge of your own town, and the goal is to turn it into a bustling metropolis by building houses and businesses. Once a house is built, you have to actively populate it with renters and after a period of time (anywhere from a few minutes to a few hours) you can return to collect your cash. Return too late, and you''ll miss your pay day completely.' FROM games WHERE igdb_id = 115543 ON CONFLICT (game_id, language_code) DO NOTHING;
