INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'J.League Winning Eleven 2010 Club Championship', 'J-League Winning Eleven 2010 Club Championship is an addition to the Winning Eleven J-League series. This game is the successor to the J-League Winning Eleven 2009 Club Championship and only features club teams (no national teams) and teams from both tiers of the J. League (totalling 36 teams). The game also features 118 foreign teams from the Premier League, Ligue 1, Serie A, Eredivisie, Primera División and a selection of teams from other leagues. This game will become the last edition of J-League Winning Eleven series.' FROM games WHERE igdb_id = 221001 ON CONFLICT (game_id, language_code) DO NOTHING;
