INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zeebo Sports Queimada', 'Zeebo Sports Queimada is a dodgeball game using Zeebo''s accelerometer controller called Boomerang. The goal is to swing the Boomerang to throw the ball and dodge while other characters move around the court. The game features also an online ranking on Zeebo-net in which players can compare their achievements.' FROM games WHERE igdb_id = 66309 ON CONFLICT (game_id, language_code) DO NOTHING;
