INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NinJump', 'Climb ninja, climb! In this fast-paced ninja running game, your goal is to climb as high as you can while avoiding evil squirrels, dive-bombing birds, enemy ninjas, throwing stars, exploding bombs & more! Effortlessly scale the side of buildings with ninja agility. Tap to jump from one wall to the other, slashing enemies in your way. Hit three matching enemies in a row for a bonus power-up boost. Grab shields for protection. Watch out for obstacles & ledges. Stay alive!' FROM games WHERE igdb_id = 324042 ON CONFLICT (game_id, language_code) DO NOTHING;
