INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Resonance of Fate', 'In this sci-fi rpg you will follow the three protagonists - Zephyr, Leanne, and Vashyron - as they form a mercenary group that take odd jobs for the populace of Basel. During their missions, they discover a plan by the city''s ruling Cardinals to subvert Zenith''s rule, and discover their own connections to the Cardinals'' plans.' FROM games WHERE igdb_id = 7159 ON CONFLICT (game_id, language_code) DO NOTHING;
