INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Smash Frenzy 4', 'Blast off with the most spectacular brick-buster yet in Smash Frenzy 4, an ingenious addition to the hit series. Aliens have kidnapped thousands of men, women, and animals and transported to another dimension. Use your ship and ball to break apart 3D levels, save the humans, and send the alien invaders home. Play the most exhilarating Smash Frenzy yet in Smash Frenzy 4 today!' FROM games WHERE igdb_id = 54376 ON CONFLICT (game_id, language_code) DO NOTHING;
