INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trainz Simulator: Classic Cabon City', 'Classic Cabon City is a large city with over 180 stations and a two-track system enabling full choice in the route to your destination. Drive two different Trams with their own cab and follow your route on the HUD interface, Switch junctions directly from the Driver''s cabin and explore the vast city laid out before you. The scenery and ambience bring life to the city with attention to detail, high-resolution textures, lighting and Shadows and a great night mode make this the most realistic driving experience to date. In addition, Classic Cabon City provides multiple locations for you to discover, such as Fun Fairs, a large Airport and a 1000m tall Skytower you can approach.' FROM games WHERE igdb_id = 11021 ON CONFLICT (game_id, language_code) DO NOTHING;
