INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Putt Putt Golf HD', 'The official Putt Putt Golf game! The legendry name in mini-golf with over 90 holes of putting fun! You don’t have to play golf to love Putt Putt mini golf, it’s a fun experience for all with the fantastically fun courses in the beautiful levels of: Fantasy Lane, Roman Road, Arctic Lands, Pirate Paradise and Jungle fever. Watch out for the water! And the giant moving snail or that strange rotating cakes! Inspired from the miniature golf putting courses from the famous Putt Putt Golf capturing all the skill and fun to make the game truly enjoyable. Do well and you might even get a medal!' FROM games WHERE igdb_id = 175064 ON CONFLICT (game_id, language_code) DO NOTHING;
