INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The UnderGarden', 'The UnderGarden is a casual Zen game that challenges players to explore beautiful underground caverns filled with strange life forms, sound, music and plenty of hidden secrets. Casual gamers with an affinity towards puzzle games will enjoy The UnderGarden''s modern exploration quest filled with brain teasing games that combine state of the art 3D rendering and physics based puzzles.' FROM games WHERE igdb_id = 14848 ON CONFLICT (game_id, language_code) DO NOTHING;
