INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Memo', 'Memo is a slice of life story set in an unnamed Japanese city that''s neither large nor small. Over the course of a few days, one will experience the life of a male transfer student named Seji who has moved several times a year for most of his life. Compelling experiences spur the youth forward as he reconnects with a childhood town.' FROM games WHERE igdb_id = 139686 ON CONFLICT (game_id, language_code) DO NOTHING;
